insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000416491', '40000000-0000-4000-8000-000000041649', 'Calcule o produto', '$d \cdot n=9-9=0.$', 1), ('70000000-0000-4000-8000-000000416492', '40000000-0000-4000-8000-000000041649', 'Interprete', 'O diretor da reta é ortogonal ao normal do plano.', 2), ('70000000-0000-4000-8000-000000416493', '40000000-0000-4000-8000-000000041649', 'Conclua', 'A reta é paralela ao plano; assim, o menor ângulo entre eles é zero grau.', 3)
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000041650', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000207', 'multiple_choice', 'hard', 'published', 'A reta r tem diretor $d=(10,1,0)$ e o plano pi tem normal $n=(1,-10,0)$. Qual é o ângulo entre r e pi?')
