insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000041701', '20000000-0000-4000-8000-000000000003', '10000000-0000-4000-8000-000000000208', 'multiple_choice', 'easy', 'published', 'A equação $(x-1)^2+(y+1)^2+(z-2)^2=16$ descreve qual superfície?')
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000000417011', '40000000-0000-4000-8000-000000041701', 'A', 'Uma esfera.', 1), ('50000000-0000-4000-8000-000000417012', '40000000-0000-4000-8000-000000041701', 'B', 'Um plano.', 2), ('50000000-0000-4000-8000-000000417013', '40000000-0000-4000-8000-000000041701', 'C', 'Um paraboloide elíptico.', 3), ('50000000-0000-4000-8000-000000417014', '40000000-0000-4000-8000-000000041701', 'D', 'Um cilindro circular.', 4)
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000041701', '50000000-0000-4000-8000-000000417011') on conflict (question_id) do update set correct_option_id = excluded.correct_option_id;
