insert into public.question_hints (id, question_id, content_markdown, sort_order) values ('60000000-0000-4000-8000-000000417011', '40000000-0000-4000-8000-000000041701', 'Compare a equação com a distância ao quadrado de um ponto fixo.', 1), ('60000000-0000-4000-8000-000000417012', '40000000-0000-4000-8000-000000041701', 'Os três termos quadráticos têm o mesmo sinal e sua soma é uma constante positiva.', 2)
insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000041701', 'Uma esfera.', 'Quádricas são superfícies descritas por equações de segundo grau em três variáveis. A forma algébrica revela a geometria: três quadrados somados descrevem uma esfera ou elipsoide, enquanto uma variável ausente indica que a curva do plano se prolonga naquela direção.') on conflict (question_id) do update set final_answer_markdown = excluded.final_answer_markdown, explanation_markdown = excluded.explanation_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000000417011', '40000000-0000-4000-8000-000000041701', 'Reconheça o padrão', 'Há três quadrados de diferenças de coordenadas.', 1), ('70000000-0000-4000-8000-000000417012', '40000000-0000-4000-8000-000000041701', 'Compare com a forma padrão', '$(x-a)^2+(y-b)^2+(z-c)^2=r^2.$', 2), ('70000000-0000-4000-8000-000000417013', '40000000-0000-4000-8000-000000041701', 'Conclua', 'Essa é exatamente a equação de uma esfera.', 3)
